                    z-index: 2400; background: rgba(0,0,0,0.8); color: white; 
                    padding: 20px; border-radius: 10px; font-size: 18px; 
                    text-align: center; display:none;

position: fixed; top: 0; left: 0; width: 100%; height: 100%; 
                    background: rgba(0,0,0,0.8); z-index: 3000; display: none;
                    justify-content: center; align-items: center;

xpath.script:
window.addEventListener('DOMContentLoaded', () => {
  const startBtn = document.getElementById('start_btn');
  const cancelBtn = document.getElementById('cancel_btn');
  const cancelBtnContainer = document.getElementById('cancel_btn_container');
  const currentTimeDiv = document.getElementById('current_time');
  const statusMessage = document.getElementById('status_message');
  let video = document.getElementById('camera_preview');
  const canvas = document.getElementById('overlay_canvas');
  const popup = document.getElementById('attendance_popup');
  const confirmBtn = document.getElementById('confirm_btn');
  const retryBtn = document.getElementById('retry_btn');

  let intervalId = null;
  let stream = null;
  let employees = [];
  let isProcessing = false;
  let matchedEmployee = null;
  let challengePassed = false;
  let capturedImage = null;

  // MediaPipe Challenge 
  let faceMesh = null;
  let mpCamera = null;
  let challengeIndex = 0;
  let mediaPipeActive = false;

  const challenges = [
    { type: 'blink', text: 'Please blink your eyes' },
    { type: 'mouth', text: 'Please open your mouth' },
    { type: 'left',  text: 'Turn your head left' },
    { type: 'right', text: 'Turn your head right' },
  ];

  // อัปเดตเวลา
  function updateTime() {
    const now = new Date();
    const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    const dateStr = now.toLocaleDateString('en-US', options);
    const timeStr = now.toLocaleTimeString('en-US', { hour12: false });
    currentTimeDiv.textContent = `${dateStr} ${timeStr}`;
  }
  setInterval(updateTime, 1000);
  updateTime();

  function showStatus(message) {
    statusMessage.textContent = message;
    statusMessage.style.display = 'block';
  }

  function hideStatus() {
    statusMessage.style.display = 'none';
  }

  function stopCamera() {
    if (intervalId) {
      clearInterval(intervalId);
      intervalId = null;
    }
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      stream = null;
    }
    video.srcObject = null;
    video.style.display = 'none';
    canvas.style.display = 'none';
    currentTimeDiv.style.display = 'none';
    cancelBtnContainer.style.display = 'none';
    hideStatus();
    isProcessing = false;
  }

  function showAttendancePopupPreview(employee) {
    const now = new Date();
    document.getElementById('employee_name').textContent = employee.name;
    document.getElementById('action_type').textContent = 'ATTENDANCE';
    document.getElementById('attendance_time').textContent = now.toLocaleString();

    const statusDiv = document.getElementById('attendance_status');
    statusDiv.innerHTML = `<p style="margin: 0; font-size: 16px; font-weight: bold;">Ready to confirm attendance</p>`;
    statusDiv.style.backgroundColor = '#fff3cd';
    statusDiv.style.color = '#856404';
    statusDiv.style.border = '1px solid #ffeeba';
    popup.style.display = 'flex';
  }

  async function processAttendance(employee) {
    try {
      showStatus('Processing attendance...');

      const imageBase64 = capturedImage;

      const res = await fetch('/hr_attendance/face_check', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          employee_id: employee.id,
          image: imageBase64,
          challenge_passed: challengePassed
        })
      });

      const data = await res.json();
      console.log("Attendance API response:", data);

      const result = data.result || data;

      // แสกนหน้าแล้ว Liveness fail → ให้สแกนหน้าใหม่
      if (!result.success) {
        popup.style.display = 'none';    
        showStatus('Liveness check failed. Please scan your face again.');
        return; 
      }

      const success = data.result && data.result.success;
      const message = data.result?.message || (success ? 'Attendance recorded successfully!' : 'Failed to record attendance');

      // แสดง popup สรุป
      const statusDiv = document.getElementById('attendance_status');
      if (success) {
        document.getElementById('action_type').style.color = '#28a745';
        statusDiv.style.backgroundColor = '#d4edda';
        statusDiv.style.color = '#155724';
      } else {
        document.getElementById('action_type').style.color = '#dc3545';
        statusDiv.style.backgroundColor = '#f8d7da';
        statusDiv.style.color = '#721c24';
      }
      statusDiv.innerHTML = `<p style="margin:0;font-size:16px;font-weight:bold;">${message}</p>`;
      popup.style.display = 'flex';
      hideStatus();

    } catch (err) {
      console.error("Attendance API error:", err);
      showStatus('Connection error. Please try again.');
    }
  }

  function onFaceMeshResults(results) {
    if (!mediaPipeActive) return;

    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!results.multiFaceLandmarks || !results.multiFaceLandmarks.length) {
      return;
    }

    const lm = results.multiFaceLandmarks[0];
    if (!lm || lm.length < 468) {
      return;
    }

    // วาด mesh (กรอบตรวจ depth)
    drawConnectors(ctx, lm, FACEMESH_TESSELATION,
      { color: '#00FFFF', lineWidth: 1 });

    // ===== Landmark ที่ใช้ =====
    const leftEyeTop = lm[159];
    const leftEyeBottom = lm[145];
    const rightEyeTop = lm[386];
    const rightEyeBottom = lm[374];
    const mouthTop = lm[13];
    const mouthBottom = lm[14];
    const nose = lm[1];

    const blink =
      Math.abs(leftEyeTop.y - leftEyeBottom.y) < 0.004 &&
      Math.abs(rightEyeTop.y - rightEyeBottom.y) < 0.004;

    const mouthOpen = Math.abs(mouthTop.y - mouthBottom.y) > 0.03;
    const MIRRORED = true;
    const headLeft  = MIRRORED ? nose.x > 0.55 : nose.x < 0.45;
    const headRight = MIRRORED ? nose.x < 0.45 : nose.x > 0.55;

    const current = challenges[challengeIndex];
    let ok = false;

    if (current?.type === 'blink') ok = blink;
    if (current?.type === 'mouth') ok = mouthOpen;
    if (current?.type === 'left') ok = headLeft;
    if (current?.type === 'right') ok = headRight;

    // ===== TEXT =====
    ctx.fillStyle = 'yellow';
    ctx.font = '26px Arial';
    ctx.fillText(`Challenge: ${current?.text}`, 20, 40);

    if (ok) {
      challengeIndex++;
      if (challengeIndex >= challenges.length) {
        challengePassed = true;

        ctx.fillStyle = 'lime';
        ctx.fillText('Challenge Passed', 20, 80);

        stopMediaPipe();
        stopCamera();

        setTimeout(() => {
          startFaceApiIdentify();
        }, 100); 
        return;
      }
    }
  }

  startBtn.onclick = async () => {
    if (isProcessing) return;
    isProcessing = true;

    resetAllState();    
    video = recreateVideoElement(); 

    showStatus('Starting face challenge...');

    video.style.display = 'block';
    canvas.style.display = 'block';
    currentTimeDiv.style.display = 'block';
    cancelBtnContainer.style.display = 'block';

    stream = await navigator.mediaDevices.getUserMedia({ video: true });
    video.srcObject = stream;
    await new Promise(r => video.onloadedmetadata = r);

    initMediaPipeChallenge();  
  };

  function initMediaPipeChallenge() {
    mediaPipeActive = true;
    challengePassed = false;
    challengeIndex = 0;

    faceMesh = new FaceMesh({
      locateFile: f => `https://cdn.jsdelivr.net/npm/@mediapipe/face_mesh/${f}`,
    });

    faceMesh.setOptions({
      maxNumFaces: 1,
      refineLandmarks: true,
      minDetectionConfidence: 0.6,
      minTrackingConfidence: 0.6,
    });

    faceMesh.onResults(onFaceMeshResults);

    mpCamera = new Camera(video, {
      onFrame: async () => {
        if (!mediaPipeActive || !faceMesh) return;
        await faceMesh.send({ image: video });
      },
      width: video.videoWidth,
      height: video.videoHeight,
    });

    mpCamera.start();

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;

    hideStatus();
    isProcessing = false;
  }

  async function startFaceApiIdentify() {
    if(intervalId || isProcessing) return;

    try {
      isProcessing = true;
      showStatus('Loading face recognition models...');

      video.style.display = 'block';
      canvas.style.display = 'block';
      currentTimeDiv.style.display = 'block';
      cancelBtnContainer.style.display = 'block';

      // โหลด models
      await faceapi.nets.tinyFaceDetector.loadFromUri('/custom_face_api_js/static/models');
      await faceapi.nets.faceLandmark68Net.loadFromUri('/custom_face_api_js/static/models');
      await faceapi.nets.faceRecognitionNet.loadFromUri('/custom_face_api_js/static/models');

      showStatus('Loading employee data...');

      // ดึง descriptors
      let response = await fetch('/hr_employee/get_descriptors', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({})
      }).then(r => r.json());

      employees = Array.isArray(response.result) ? response.result : [];
      employees = employees.filter(emp => {
        try {
          const bytes = atob(emp.descriptor);
          const f32 = new Float32Array(new Uint8Array([...bytes].map(c => c.charCodeAt(0))).buffer);
          if(f32.length !== 128) return false;
          emp.descriptor = f32;
          return true;
        } catch(e){
          console.error("Descriptor decode error:", e, emp);
          return false;
        }
      });

      showStatus('Starting camera...');

      stream = await navigator.mediaDevices.getUserMedia({ video: true });
      video.srcObject = stream;
      await new Promise(resolve => video.onloadedmetadata = resolve);

      isProcessing = false;
      hideStatus();

      intervalId = setInterval(async () => {
        try {
          const detections = await faceapi.detectAllFaces(
            video,
            new faceapi.TinyFaceDetectorOptions({ inputSize: 512, scoreThreshold: 0.5 })
          ).withFaceLandmarks().withFaceDescriptors();

          const ctx = canvas.getContext('2d');
          ctx.clearRect(0, 0, canvas.width, canvas.height);

          if (detections.length > 0) {
            const det = detections[0];
            let bestMatch = { name: "Unknown", distance: 1.0, id: null };

            for(const emp of employees){
              const dist = faceapi.euclideanDistance(det.descriptor, emp.descriptor);
              if(dist < bestMatch.distance && dist < 0.5){
                bestMatch = { name: emp.name, distance: dist, id: emp.id };
              }
            }

            // วาดกรอบ
            const box = det.detection.box;
            const scaleX = canvas.width / video.videoWidth;
            const scaleY = canvas.height / video.videoHeight;
            const x = box.x * scaleX;
            const y = box.y * scaleY;
            const w = box.width * scaleX;
            const h = box.height * scaleY;

            ctx.strokeStyle = bestMatch.name === "Unknown" ? "yellow" : "lime";
            ctx.lineWidth = 3;
            ctx.strokeRect(x, y, w, h);
            ctx.fillStyle = ctx.strokeStyle;
            ctx.font = "20px Arial";
            ctx.fillText(bestMatch.name, x, y - 10);

            if(bestMatch.name === "Unknown"){
              showStatus('Unknown face detected. Please try again.');
            } else {
              showStatus(`Found: ${bestMatch.name}. Ready to confirm.`);
            }

            if(bestMatch.id && bestMatch.name !== "Unknown" && !isProcessing){
              isProcessing = true;
              clearInterval(intervalId);
              intervalId = null;
              matchedEmployee = { id: bestMatch.id, name: bestMatch.name };
              capturedImage = captureCurrentFrame(); 
              stopFaceApiCamera();
              showAttendancePopupPreview(matchedEmployee);
            }

          }
        } catch(error) {
          console.error('Detection error:', error);
          showStatus('Detection error. Please try again.');
        }
      }, 300);

    } catch (error) {
      console.error('Error starting face recognition:', error);
      showStatus('Error: ' + error.message);  
      stopCamera();
    }
  };

  cancelBtn.onclick = () => {
    resetAllState();
  };

  confirmBtn.onclick = async () => {
    if (matchedEmployee) {
      await processAttendance(matchedEmployee);
    }
    resetAllState();
  };

  retryBtn.onclick = () => {
    resetAllState();
    startBtn.click();
  };

  function captureCurrentFrame() {
    const captureCanvas = document.createElement('canvas');
    captureCanvas.width = video.videoWidth;
    captureCanvas.height = video.videoHeight;
    const ctx = captureCanvas.getContext('2d');
    ctx.drawImage(video, 0, 0);
    return captureCanvas.toDataURL('image/jpeg');
  }

function stopMediaPipe() {
  console.log('Stop MediaPipe');
  mediaPipeActive = false;

  if (mpCamera) {
    mpCamera.stop();
    mpCamera = null;
  }

  if (faceMesh) {
    faceMesh = null;
  }
}

function stopFaceApiCamera() {
  if (intervalId) {
    clearInterval(intervalId);
    intervalId = null;
  }

  if (stream) {
    stream.getTracks().forEach(t => t.stop());
    stream = null;
  }

  video.srcObject = null;
  video.style.display = 'none';
  canvas.style.display = 'none';
  currentTimeDiv.style.display = 'none';
  cancelBtnContainer.style.display = 'none';
}

function resetAllState() {
  console.log('Reset all state');

  isProcessing = false;
  mediaPipeActive = false;
  challengePassed = false;
  challengeIndex = 0;

  matchedEmployee = null;
  capturedImage = null;

  // stop ทุกอย่าง
  stopMediaPipe();
  stopFaceApiCamera();

  // reset UI
  popup.style.display = 'none';
  hideStatus();
}

function recreateVideoElement() {
  if (stream) {
    stream.getTracks().forEach(t => t.stop());
    stream = null;
  }

  if (mpCamera) {
    mpCamera.stop();
    mpCamera = null;
  }

  if (video) {
    video.pause();
    video.srcObject = null;
    video.remove();
  }

  const newVideo = document.createElement('video');
  newVideo.id = 'camera_preview';
  newVideo.autoplay = true;
  newVideo.playsInline = true;
  newVideo.muted = true;
  newVideo.style = `
    position:fixed;
    top:0; left:0;
    width:100vw; height:100vh;
    object-fit:cover;
    z-index:2000;
    transform: scaleX(-1);
    display:none;
  `;

  document.body.appendChild(newVideo);
  return newVideo;
}
});
